// querySelector — returns first match (like CSS selectors)
const title = document.querySelector('h1');
const btn = document.querySelector('#submit-btn');       // by id
const card = document.querySelector('.card');            // by class
const input = document.querySelector('input[type=text]'); // by attribute

// querySelectorAll — returns ALL matches as a NodeList
const allButtons = document.querySelectorAll('button');
const allCards = document.querySelectorAll('.card');

// Convert NodeList to array for array methods
const cardsArray = Array.from(allCards);
cardsArray.forEach(card => console.log(card));

// Older alternatives (still common)
document.getElementById('my-id');          // fast, id only
document.getElementsByClassName('my-cls'); // HTMLCollection (live)

const heading = document.querySelector('h1');

// Reading
console.log(heading.textContent);  // 'Hello World' — text only (safe)
console.log(heading.innerHTML);    // '<strong>Hello</strong> World' — includes HTML

// Writing text — use textContent for user data (prevents XSS)
heading.textContent = 'New Heading';

// Writing HTML — only when content is trusted/controlled
const container = document.querySelector('#output');
container.innerHTML = '<p>Generated at <strong>' + new Date().toLocaleTimeString() + '</strong></p>';

// Form input values
const input = document.querySelector('#username');
console.log(input.value);    // read current value
input.value = 'Prashant';   // set value

const card = document.querySelector('.card');

card.classList.add('active');          // add a class
card.classList.remove('hidden');       // remove a class
card.classList.toggle('open');         // add if missing, remove if present
card.classList.contains('active');     // returns true/false
card.classList.replace('old', 'new');  // swap classes

// Toggle with condition
const isDark = true;
document.body.classList.toggle('dark-mode', isDark);  // true = add, false = remove

const link = document.querySelector('a');

link.getAttribute('href');              // read any attribute
link.setAttribute('href', '/about');    // set any attribute
link.removeAttribute('disabled');       // remove attribute
link.hasAttribute('disabled');          // check attribute

// data-* attributes — stored in element.dataset
// <button data-user-id="42">Click</button>
const btn = document.querySelector('button');
console.log(btn.dataset.userId);    // '42' (camelCase from data-user-id)
btn.dataset.userId = '99';          // set

// Style property
const box = document.querySelector('.box');
box.style.backgroundColor = '#4fd1c5';  // camelCase CSS property
box.style.width = '200px';
